        return (200, grades)
    if path == "/grades" and method == "POST":
        if body and body.get("lesson") and 0 <= body.get("grade", -1) <= 100:
            grades[body["lesson"]] = body["grade"]
            return (201, body)
        return (400, {"hata": "geçersiz not"})
